    # e^(A-X) times X^(N+1) < N!/2 ensures both Li barriers.
    if not (X>A and X>8*(9+d)): return False
    if not (2*X**(N+1)*1000**(X-A)<fac(N)*2718**(X-A)):return False
    h=full(N-1)+sum(F(v,B**j) for j,v in enumerate(co,1) if v<0)
